# Fitting-layer regression tests: every sub-model and functional form is fitted on a 200-person
# subsample (the reading-score JB cases on all 500 children) and compared with the reference values in
# golden/fit_golden.rds (generated by data-raw/make_golden_fits.R). The optimizer and seeds are fixed,
# so agreement is tight on one platform; the tolerances allow for the last digits to move across
# OpenMx builds. A fit is compared with its reference only after it has passed the convergence and
# admissibility checks of getDiagnostics(): agreement with a reference is not evidence that the
# solution is statistically acceptable.

# These references did not converge. Keep exclusions explicit and fixed: replacing a reference file
# must not silently reduce the checked model coverage. The four math-score JB cases fit scores that
# are nearly linear over the study (acceleration ratio about 0.1 per year): the random-ratio variance
# comes out negative and the fixed-ratio fits are weakly identified, so these fits stop with status 6;
# JB coverage comes from the reading-score cases. MIX_MED_LIN stops with status 5.
.known_nonconverged_golden <- c("LGCM_JB_f", "LGCM_JB_r", "LCSM_JB_f", "LCSM_JB_r", "MIX_MED_LIN")
# These references reach status 0, but their solutions are inadmissible on the 200-person subsample: a
# class or group covariance matrix of the growth factors is indefinite (in MIX_LGCM_BLS_f with a negative
# variance), or, in MIX_LCSM_NonP, a class has no assigned persons and the standard errors are
# incomplete. They are kept as fixtures for getDiagnostics(), not as model coverage.
.known_inadmissible_golden <- c("MGroup_LGCM_BLS_f", "MIX_LGCM_LIN", "MIX_LGCM_BLS_f", "MIX_LCSM_NonP", "MIX_MGM_LIN")

test_that("golden reference coverage cannot silently shrink", {
  golden <- readRDS(test_path("golden", "fit_golden.rds"))
  excluded <- vapply(golden, function(x) !is.null(x$error) || !isTRUE(x$status == 0), logical(1))
  expect_setequal(names(golden)[excluded], .known_nonconverged_golden)
  expect_true(all(.known_inadmissible_golden %in% names(golden)[!excluded]))
  expect_equal(sum(!excluded) - length(.known_inadmissible_golden), 33L)
})

for (.golden_exclusion in .known_nonconverged_golden) {
  test_that(paste("known unavailable numerical reference:", .golden_exclusion), {
    skip(paste("Reference did not converge:", .golden_exclusion,
               "(reported explicitly; no numerical agreement is claimed)"))
  })
}

test_that("fits reproduce the stored reference values for every sub-model and functional form", {
  skip_on_cran()
  golden_path <- test_path("golden", "fit_golden.rds")
  golden <- readRDS(golden_path)
  dat <- .golden_data()
  cases <- .golden_cases()
  expect_setequal(names(golden), names(cases))
  for (nm in setdiff(names(cases), .known_inadmissible_golden)) {
    ref <- golden[[nm]]
    # Reference fits that did not converge are not compared (their last digits are not stable).
    if (!is.null(ref$error) || !isTRUE(ref$status == 0)) next
    res <- .fit_golden_case(cases[[nm]], .golden_case_data(cases[[nm]], dat))
    # Validity first: convergence, admissible covariance matrices, a positive-definite Hessian and
    # complete standard errors; then numerical agreement.
    expect_equal(res$status, 0, info = nm)
    expect_identical(res$issues, character(0), info = nm)
    expect_equal(res$minus2LL, ref$minus2LL, tolerance = 1e-6, info = nm)
    expect_equal(names(res$estimates), names(ref$estimates), info = nm)
    expect_equal(res$estimates, ref$estimates, tolerance = 1e-4, info = nm)
  }
})

test_that("getDiagnostics() reports the inadmissible reference solutions", {
  skip_on_cran()
  golden <- readRDS(test_path("golden", "fit_golden.rds"))
  cases <- .golden_cases()
  for (nm in .known_inadmissible_golden) {
    res <- .fit_golden_case(cases[[nm]], .golden_case_data(cases[[nm]]))
    expect_equal(res$minus2LL, golden[[nm]]$minus2LL, tolerance = 1e-6, info = nm)
    expect_gt(length(res$issues), 0, label = paste("number of diagnostic issues of", nm))
  }
})
